package com.quincaisoft.platformcontrol.infrastructure;import jakarta.persistence.*;import java.util.*;import java.time.*;
@Entity @Table(name="platform_support_grant")public class SupportGrant{@Id public UUID id;@Column(name="tenant_id")public UUID tenantId;@Column(name="company_id")public UUID companyId;@Column(name="branch_id")public UUID branchId;@Column(name="owner_actor_id")public UUID ownerActorId;@Column(name="operator_id")public UUID operatorId;@Column(name="approved_by")public UUID approvedBy;@Column(name="revoked_by")public UUID revokedBy;public String status;@Column(name="expires_at")public Instant expiresAt;@Column(name="created_at")public Instant createdAt;@Column(name="ticket_reference")public String ticketReference;public String reason;@Version public long version;}
